/**
 * Finds the maximum number in an array of numbers.
 * 
 * @param numbers - An array of numerical values.
 * @returns The maximum number found in the array.
 * @throws {Error} If the array is empty.
 */
export function findMaxNumber(numbers: number[]): number {
  // Validate that the array is not empty to avoid returning -Infinity or NaN
  if (!Array.isArray(numbers) || numbers.length === 0) {
    throw new Error("Cannot find the maximum number in an empty or invalid array.");
  }

  // Use Math.max with the spread operator for a concise and idiomatic solution.
  // Note: For extremely large arrays (> 100,000 elements), a standard reduce loop 
  // might be preferred to avoid call stack size limits with the spread operator.
  let max = numbers[0];

  for (let i = 1; i < numbers.length; i++) {
    if (numbers[i] > max) {
      max = numbers[i];
    }
  }

  return max;
}

/**
 * Asynchronously finds the maximum number in an array of numbers.
 * Useful when processing large datasets chunk by chunk or fetching from a stream.
 * 
 * @ammatory numbers - A promise resolving to an array of numbers, or an array of numbers.
 * @returns A promise that resolves to the maximum number.
 */
export async function findMaxNumberAsync(numbers: number[] | Promise<number[]>): Promise<number> {
  const resolvedNumbers = await numbers;
  return findMaxNumber(resolvedNumbers);
}
