/**
 * Calculates the factorial of a given non-negative integer.
 * Iterative approach to avoid call stack size limits associated with recursion.
 * 
 * @param n - A non-negative integer (0 <= n <= 170 to avoid Infinity with standard numbers).
 * @returns The factorial of the input number.
 * @throws Will throw an error if the input is negative or not a safe integer.
 */
function calculateFactorial(n: number): number {
    // Validate that the input is a valid integer
    if (!Number.isInteger(n)) {
        throw new Error('Factorial is only defined for integer values.');
    }

    // Validate that the input is non-negative
    if (n < 0) {
        throw new Error('Factorial is not defined for negative numbers.');
    }

    // 0! and 1! are both 1
    if (n === 0 || n === 1) {
        return 1;
    }

    // JavaScript numbers lose precision beyond 170! (results in Infinity)
    if (n > 170) {
        throw new Error('Input is too large; results in Infinity due to number precision limits.');
    }

    let result: number = 1;

    // Iterative multiplication for optimal performance and memory safety
    for (let i = 2; i <= n; i++) {
        result *= i;
    }

    return result;
}

/**
 * Calculates the factorial of a number asynchronously.
 * Useful for integration into non-blocking event loops or pipelines.
 * 
 * @param n - A non-negative integer.
 * @returns A promise that resolves to the factorial of the input number.
 */
async function calculateFactorialAsync(n: number): Promise<number> {
    // Simulate non-blocking execution using microtask queue
    return Promise.resolve().then(() => calculateFactorial(n));
}

// Exporting functions for module usage
export { calculateFactorial, calculateFactorialAsync };
